import React, { useEffect, useState } from "react";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import axios from "axios";

export default function LudoBoard({ gameId, playerId }) {
  const [gameState, setGameState] = useState(null);
  const [diceValue, setDiceValue] = useState(null);
  const [client, setClient] = useState(null);
  const [rollCount, setRollCount] = useState(0);
  const [feeDeducted, setFeeDeducted] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);

    const stompClient = new Client({
      webSocketFactory: () => socket,
      onConnect: () => {
        console.log("🟢 Connected to WebSocket");
        stompClient.subscribe(`/topic/game/${gameId}`, (msg) => {
          const state = JSON.parse(msg.body);
          setGameState(state);
        });
      },
      onStompError: (frame) => {
        console.error("❌ WebSocket error:", frame);
      },
    });

    stompClient.activate();
    setClient(stompClient);

    return () => {
      stompClient.deactivate();
    };
  }, [gameId]);

  const rollDice = async () => {
    const roll = Math.floor(Math.random() * 6) + 1;
    setDiceValue(roll);

    try {
      const token = localStorage.getItem("authToken");
      const res = await axios.post(
        `http://localhost:8080/api/game/${gameId}/roll`,
        {},
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setRollCount(res.data.rollCount);
      setFeeDeducted(res.data.feeDeducted);

      if (res.data.feeDeducted && rollCount < 2) {
        console.log("✅ Entry fee deducted after second roll.");
      }
    } catch (err) {
      console.error("❌ Fee deduct or roll track failed:", err);
    }
  };

  const sendMove = (tokenIndex) => {
    if (!client || diceValue === null) return;

    client.publish({
      destination: "/app/game/move",
      body: JSON.stringify({
        gameId,
        playerId,
        tokenIndex,
        diceValue,
      }),
    });

    setDiceValue(null);
  };

  if (!gameState)
    return <div className="text-center mt-6">⏳ Loading game state...</div>;

  return (
    <div className="max-w-3xl mx-auto mt-8 p-4 bg-gray-100 rounded-lg shadow">
      <h2 className="text-xl font-semibold text-indigo-700 mb-4 text-center">
        🎯 Ludo Game Board - Game ID: {gameId}
      </h2>

      <div className="flex justify-between items-center mb-4">
        <div>
          <strong>Current Turn:</strong> Player {gameState.currentPlayer + 1}
        </div>
        {gameState.gameOver ? (
          <div className="text-green-700 font-bold">🏁 Game Over</div>
        ) : (
          <div className="text-blue-600">
            🎲 Dice: {diceValue ? diceValue : "Not rolled"}
          </div>
        )}
      </div>

      {gameState.playerTokens.map((tokens, idx) => (
        <div key={idx} className="mb-3">
          <h3 className="text-md font-semibold mb-1">
            Player {idx + 1} Tokens:
          </h3>
          <div className="flex gap-3">
            {tokens.map((pos, tIdx) => (
              <button
                key={tIdx}
                onClick={() => sendMove(tIdx)}
                disabled={
                  gameState.currentPlayer !== playerId || diceValue === null
                }
                className={`px-3 py-1 border rounded-md text-sm font-medium shadow-sm ${
                  pos >= 0 ? "bg-green-300" : "bg-gray-300"
                } ${
                  gameState.currentPlayer === playerId && diceValue !== null
                    ? "hover:bg-green-500 cursor-pointer"
                    : "cursor-not-allowed"
                }`}
              >
                🎯 Token {tIdx + 1} - Pos: {pos === -1 ? "Home" : pos}
              </button>
            ))}
          </div>
        </div>
      ))}

      {!gameState.gameOver && gameState.currentPlayer === playerId && (
        <div className="mt-6 text-center">
          <button
            onClick={rollDice}
            className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-2 px-4 rounded"
          >
            🎲 Roll Dice
          </button>
          <p className="text-sm mt-2 text-gray-600">
            🔄 Rolls: {rollCount} | 💰 Fee Deducted:{" "}
            {feeDeducted ? "✅ Yes" : "❌ No"}
          </p>
        </div>
      )}
    </div>
  );
}
